compile.workshop:
variables {
    global:
        0: g
    player:
        0: pv
}

//Optimize for size enabled
rule ("builtins") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Chase Player Variable At Rate(Event Player, pv, False, True, None);
        Chase Player Variable At Rate(Event Player, pv, False, True, None);
        Apply Impulse(Event Player, Up, 1, To World, Cancel Contrary Motion XYZ);
        Start Throttle In Direction(Event Player, Up, Global.g, To World, Replace existing throttle, Direction and Magnitude);
        Create Icon(All Players(All Teams), Vector(True, 2, 3), Flag, Visible To and Position, Color(Blue), True);
        Create HUD Text(All Players(All Teams), Null, Custom String("h {0}", Global.g), Custom String("t {0} {0} {0} {1}", Global.g, Add(Global.g, True)), Left, 6, Null, Color(White), Color(White), Visible To and String, Default Visibility);
        Create HUD Text(All Players(All Teams), Custom String("h"), Null, If-Then-Else(Global.g, Global.g, Custom String("z")), Top, False, Color(White), Null, Color(White), Visible To and String, Default Visibility);
        If(Is Firing Secondary(Event Player));
            Set Global Variable(g, 1);
        End;
        If(Compare(Current Game Mode, !=, Game Mode(Skirmish)));
            Set Global Variable(g, 2);
    }
}

